const funds=[
{ticker:'VOO',name:'Vanguard S&P 500 ETF',issuer:'Vanguard',fee:.03,exposure:'US large-cap stocks',index:'S&P 500',url:'https://advisors.vanguard.com/investments/products/new/voo/vanguard-sp-500-etf'},
{ticker:'IVV',name:'iShares Core S&P 500 ETF',issuer:'iShares / BlackRock',fee:.03,exposure:'US large-cap stocks',index:'S&P 500',url:'https://www.ishares.com/us/products/239726/'},
{ticker:'QQQM',name:'Invesco NASDAQ 100 ETF',issuer:'Invesco',fee:.15,exposure:'Nasdaq-listed large non-financial companies',index:'Nasdaq-100',url:'https://www.invesco.com/us/en/financial-products/etfs/invesco-nasdaq-100-etf.html'},
{ticker:'VXUS',name:'Vanguard Total International Stock ETF',issuer:'Vanguard',fee:.05,exposure:'Developed & emerging markets outside the US',index:'FTSE Global All Cap ex US',url:'https://investor.vanguard.com/investment-products/list/etfs'},
{ticker:'VTI',name:'Vanguard Morningstar Total Stock Market ETF',issuer:'Vanguard',fee:.03,exposure:'Broad US stock market',index:'Morningstar US Total Market',url:'https://workplace.vanguard.com/assets/corp/fund_communications/pdf_publish/us-products/fact-sheet/F0970.pdf'}];
const colors=['#247c92','#b68a42','#7867b1','#cb6a67'];let selected=['VOO','QQQM','VXUS'];const $=id=>document.getElementById(id);const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);let saved;try{saved=JSON.parse(localStorage.getItem('etf-lens'));if(saved?.selected?.length){const valid=saved.selected.filter((x,i,a)=>funds.some(f=>f.ticker===x)&&a.indexOf(x)===i).slice(0,4);if(valid.length)selected=valid;}for(const id of ['initial','monthly','years','rate'])if(Number.isFinite(saved?.[id]))$(id).value=saved[id];}catch{}
function current(){return selected.map(t=>funds.find(f=>f.ticker===t));}
function scenario(){return {initial:Number($('initial').value),monthly:Number($('monthly').value),years:Number($('years').value),rate:Number($('rate').value)};}
function valid(){return ['initial','monthly','years','rate'].every(id=>$(id).value!==''&&$(id).checkValidity());}
function balances(s,fee){const result=[s.initial];let n=s.initial;const r=Math.pow(1+(s.rate-fee)/100,1/12)-1;for(let i=1;i<=s.years*12;i++){n=n*(1+r)+s.monthly;if(i%12===0)result.push(n);}return result;}
function persist(){try{localStorage.setItem('etf-lens',JSON.stringify({...scenario(),selected}));}catch{}}
function render(){const fs=current();$('count').textContent=fs.length+' / 4';$('cards').innerHTML=fs.map((f,i)=>`<article class="fund-card" style="--color:${colors[i]}"><span class="ticker">${f.ticker}</span><button class="remove" data-remove="${f.ticker}" aria-label="Remove ${f.ticker}" ${fs.length===1?'disabled':''}>×</button><p>${f.name}</p><small>${f.fee.toFixed(2)}% expense ratio</small></article>`).join('');$('comparison').innerHTML='<thead><tr><th>Fund overview</th>'+fs.map((f,i)=>`<th style="color:${colors[i]}">${f.ticker}</th>`).join('')+'</tr></thead><tbody>'+[['Fund name',f=>f.name],['Issuer',f=>f.issuer],['Expense ratio',f=>f.fee.toFixed(2)+'% annually'],['Annual cost per $10,000',f=>money(f.fee*100)],['Market exposure',f=>f.exposure],['Benchmark',f=>f.index],['Trading currency',()=> 'USD'],['Source',f=>`<a href="${f.url}" target="_blank" rel="noopener">Issuer documents</a>`]].map(([label,fn])=>'<tr><td>'+label+'</td>'+fs.map(f=>'<td>'+fn(f)+'</td>').join('')+'</tr>').join('')+'</tbody>';$('legend').innerHTML=fs.map((f,i)=>`<span><i class="key" style="background:${colors[i]}"></i>${f.ticker}</span>`).join('');search();plot();renderDividends();}
function plot(){const s=scenario();$('yearLabel').textContent=s.years+' years';if(!valid()){updateDividendEstimates();$('validation').textContent='Enter valid values: nonnegative investments, 1–40 years, and −20% to 30% return.';return;}$('validation').textContent='';updateDividendEstimates();persist();const series=current().map(f=>balances(s,f.fee)),base=balances(s,0);const max=Math.max(1,...base,...series.flat())*1.08;const x=t=>65+t/s.years*665,y=v=>250-v/max*220;let svg='<svg viewBox="0 0 760 290" xmlns="http://www.w3.org/2000/svg"><title>Hypothetical investment growth after expenses</title>';for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="65" y1="${y(v)}" x2="730" y2="${y(v)}" stroke="#e7edf0"/><text x="53" y="${y(v)+4}" text-anchor="end" fill="#7a8c97" font-size="11">${v>=1000?'$'+Math.round(v/1000)+'k':money(v)}</text>`;}for(let i=0;i<=4;i++){let t=Math.round(s.years*i/4);svg+=`<text x="${x(t)}" y="277" text-anchor="middle" fill="#7a8c97" font-size="12">${t}</text>`;}series.forEach((points,i)=>{svg+=`<path d="${points.map((v,t)=>(t?'L':'M')+x(t).toFixed(2)+','+y(v).toFixed(2)).join(' ')}" fill="none" stroke="${colors[i]}" stroke-width="${3-i*.35}"/>`;});$('chart').innerHTML=svg+'</svg>';$('outcomes').innerHTML=current().map((f,i)=>`<div class="outcome"><span style="color:${colors[i]}">${f.ticker}</span><strong>${money(series[i].at(-1))}</strong><small>${money(base.at(-1)-series[i].at(-1))} fee drag</small></div>`).join('');}
function search(){const q=$('search').value.trim().toLowerCase();$('results').replaceChildren();if(!q)return;const hits=funds.filter(f=>!selected.includes(f.ticker)&&(f.ticker+' '+f.name).toLowerCase().includes(q));if(selected.length>=4){$('results').textContent='Remove a fund to add another.';return;}if(!hits.length){$('results').textContent='No matches in this curated list. Try VOO, IVV, QQQM, VXUS or VTI.';return;}hits.forEach(f=>{const b=document.createElement('button');b.textContent=f.ticker+' · '+f.name;b.onclick=()=>{selected.push(f.ticker);$('search').value='';render();};$('results').append(b);});}
$('cards').onclick=e=>{const t=e.target.dataset.remove;if(t&&selected.length>1){selected=selected.filter(x=>x!==t);render();}};$('search').oninput=search;['initial','monthly','years','rate'].forEach(id=>$(id).oninput=plot);$('reset').onclick=()=>{selected=['VOO','QQQM','VXUS'];$('search').value='';render();};$('export').onclick=()=>{if(!valid()||!dividendInputsValid())return;const s=scenario();const rows=[['Ticker','Fund','Expense ratio (%)','Exposure','Projected balance USD','Fee drag USD','Assumed dividend yield (%)','Annual dividends on starting amount USD','Monthly equivalent USD','Annual dividends at horizon balance USD','Source'],...current().map(f=>{const b=balances(s,f.fee).at(-1);return [f.ticker,f.name,f.fee,f.exposure,b.toFixed(2),(balances(s,0).at(-1)-b).toFixed(2),yieldFor(f.ticker),dividendEstimate(s.initial,yieldFor(f.ticker)).toFixed(2),(dividendEstimate(s.initial,yieldFor(f.ticker))/12).toFixed(2),dividendEstimate(b,yieldFor(f.ticker)).toFixed(2),f.url];}),[],['Snapshot','2026-11-18'],['Starting USD',s.initial],['Monthly USD',s.monthly],['Years',s.years],['Assumed gross return %',s.rate],['Note','Hypothetical; dividend yields are user assumptions (default 2%, not reported yields). Monthly income is an average; horizon income is a run rate, not cumulative. Dividends are included in total return; do not add to projected balance. Excludes taxes, spreads, commissions and inflation.']];const csv=rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='etf-lens-comparison.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};render();
